package com.classvoice.controller; import com.classvoice.dao.FeedbackDAO; import com.classvoice.model.User; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/student/history") public class FeedbackHistoryServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{User u=(User)r.getSession().getAttribute("user");r.setAttribute("history",new FeedbackDAO().findByStudent(u.getUserId()));r.getRequestDispatcher("/WEB-INF/views/feedback-history.jsp").forward(r,p);}catch(Exception e){throw new ServletException(e);}}}
